// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherCartel} from "../src/EtherCartel.sol";

contract InvMutTest is Test {
    EtherCartel c;
    function setUp() public { c = new EtherCartel(); }
    function testRegression_property() public {
        vm.deal(address(this), 1 ether);
        c.seedMarket{value: 0.5 ether}(1000);

        c.getFreeKilo();

        vm.warp(block.timestamp + 86400);

        c.collectDrugs(address(0));

        uint256 refResult = c.calculateDrugSell(1);

        uint256 expected = c.calculateTrade(1, c.marketDrugs(), address(c).balance);
        assertEq(refResult, expected);
    }
}
